"""Tests for the helpers in bake_hair_operator.py which do not need an actual bake.

The atlas packing, colour dilation, temporary materials, light placement and the restoring of the scene are
all tested on hand made data here. The full bake runs in pipeline_test.py.
"""

import os
import tempfile
import types

import bpy
import pytest
from mathutils import Vector

from .haireditor_fixtures import (bake_module as bake, cardgenerators as cg, scratch, select, link,
                                  make_hair_curves, bundle_of_strands, make_grid, make_separate_quads,
                                  make_material, make_rig, surface_link_source, operator_mock)

BakeOperator = bake.MPFB_OT_BakeHair_Operator


def _bmesh_of(obj):
    import bmesh

    bm = bmesh.new()
    bm.from_mesh(obj.data)
    bm.faces.ensure_lookup_table()
    return bm


def _island_stand_ins(loop_counts):
    """Islands for _pick_atlas_variants, which only looks at how many loops each face has."""
    return [[types.SimpleNamespace(loops=[None] * count)] for count in loop_counts]


