def _face_uvs(obj):
    uv_layer = obj.data.uv_layers[0]
    return {face.index: [tuple(round(value, 5) for value in uv_layer.data[index].uv) for index in face.loop_indices]
            for face in obj.data.polygons}


def _in_unit_square(uvs):
    return all(-1e-5 <= u <= 1.0 + 1e-5 and -1e-5 <= v <= 1.0 + 1e-5 for u, v in uvs)


def test_generated_uvs_are_packed_into_cells_and_shared(scratch):
    cards = make_separate_quads("bake_pack", 8)
    plan = bake._pack_card_uvs_into_grid(cards, 0.5, resolution=256)

    during = _face_uvs(cards)
    baked = [face for face, uvs in during.items() if _in_unit_square(uvs)]
    parked = [face for face, uvs in during.items() if all(u >= bake._UV_PARKING_OFFSET for u, _v in uvs)]
    assert len(baked) == 4 and len(parked) == 4, "half the cards are baked, the rest are parked off the texture"
    boxes = sorted((min(u for u, _v in during[face]), max(u for u, _v in during[face]),
                    min(v for _u, v in during[face]), max(v for _u, v in during[face])) for face in baked)
    for index, first in enumerate(boxes):
        for second in boxes[index + 1:]:
            apart = (first[1] <= second[0] + 1e-6 or second[1] <= first[0] + 1e-6
                     or first[3] <= second[2] + 1e-6 or second[3] <= first[2] + 1e-6)
            assert apart, f"two baked cards share a cell: {boxes}"

    bake._apply_card_atlas(cards, plan)
    after = _face_uvs(cards)
    assert all(_in_unit_square(uvs) for uvs in after.values())
    baked_layouts = {tuple(during[face]) for face in baked}
    for face in parked:
        assert tuple(after[face]) in baked_layouts, "a shared card has to land exactly on a baked one"


@pytest.mark.parametrize("count, fraction", [(8, 0.5), (100, 0.1), (10, 0.3)])
def test_shared_cards_are_spread_over_the_variants(count, fraction):
    """Every baked variant should stand in for about the same number of cards, or the repetition shows."""
    variants, assignment = bake._pick_atlas_variants(_island_stand_ins([4] * count), fraction)
    uses = {variant: 0 for variant in variants}
    for variant in assignment.values():
        uses[variant] += 1
    assert max(uses.values()) - min(uses.values()) <= 1, f"copies per variant: {uses}"


def test_cells_keep_a_margin_for_the_dilation(scratch):
    cards = make_separate_quads("bake_margin", 4)
    bake._pack_card_uvs_into_grid(cards, 1.0, resolution=64)
    for uvs in _face_uvs(cards).values():
        assert min(u for u, _v in uvs) > 0.0 and max(v for _u, v in uvs) < 1.0


def test_atlas_with_a_changed_mesh_leaves_the_odd_card_alone(scratch):
    """If the plan does not match the mesh any more, the card is skipped instead of getting garbage UVs."""
    cards = make_separate_quads("bake_stale_plan", 2)
    before = _face_uvs(cards)
    bake._apply_card_atlas(cards, {"final_uvs": {0: [(0.5, 0.5)] * 3}})
    assert _face_uvs(cards) == before


def test_unwrapped_atlas_bakes_only_the_variants(scratch):
    """Without a generated layout the variants are smart projected and the rest parked, then given the variant UVs."""
    cards = make_separate_quads("bake_unwrapped", 6, uv_per_card=False)
    select(cards)
    plan = bake._prepare_card_atlas(cards, 0.5)
    assert len(plan["variant_uvs"]) == 3
    assert len(plan["assignment"]) == 3
    during = _face_uvs(cards)
    assert sum(1 for uvs in during.values() if _in_unit_square(uvs)) == 3
    assert sum(1 for uvs in during.values() if min(u for u, _v in uvs) >= bake._UV_PARKING_OFFSET - 1e-5) == 3

    bake._apply_card_atlas(cards, plan)
    assert all(_in_unit_square(uvs) for uvs in _face_uvs(cards).values())
    assert cards.mode == 'OBJECT'


