def _rgba_image(name, size=8):
    import numpy as np

    image = bpy.data.images.new(name, size, size, alpha=True, float_buffer=True)
    pixels = np.zeros((size, size, 4), dtype=np.float32)
    return image, pixels


def _write(image, pixels):
    image.pixels.foreach_set(pixels.ravel())


def _read(image, size=8):
    import numpy as np

    flat = np.empty(size * size * 4, dtype=np.float32)
    image.pixels.foreach_get(flat)
    return flat.reshape(size, size, 4)


def test_dilation_bleeds_colour_but_not_alpha(scratch):
    image, pixels = _rgba_image("bake_dilate")
    pixels[4, 4] = (1.0, 0.0, 0.0, 1.0)
    _write(image, pixels)
    bake._dilate_image_colour(image, passes=2)
    result = _read(image)
    for row, column in ((4, 5), (4, 3), (3, 4), (5, 4), (4, 6), (2, 4)):
        assert tuple(result[row, column, :3]) == pytest.approx((1.0, 0.0, 0.0)), (row, column)
        assert result[row, column, 3] == 0.0, "the silhouette has to stay exactly as baked"
    assert tuple(result[0, 0, :3]) == pytest.approx((0.0, 0.0, 0.0)), "two passes only reach two pixels out"


def test_dilation_averages_its_neighbours(scratch):
    image, pixels = _rgba_image("bake_dilate_average")
    pixels[4, 3] = (1.0, 0.0, 0.0, 1.0)
    pixels[4, 5] = (0.0, 0.0, 1.0, 1.0)
    _write(image, pixels)
    bake._dilate_image_colour(image, passes=1)
    assert tuple(_read(image)[4, 4, :3]) == pytest.approx((0.5, 0.0, 0.5))


@pytest.mark.parametrize("alpha", [0.0, 1.0])
def test_dilation_leaves_empty_and_full_images_alone(scratch, alpha):
    image, pixels = _rgba_image(f"bake_dilate_{alpha}")
    pixels[:, :] = (0.2, 0.4, 0.6, alpha)
    _write(image, pixels)
    bake._dilate_image_colour(image)
    assert (_read(image) == pixels).all()


def test_dilation_does_not_wrap_around_the_texture(scratch):
    image, pixels = _rgba_image("bake_dilate_wrap")
    pixels[4, 0] = (1.0, 0.0, 0.0, 1.0)
    _write(image, pixels)
    bake._dilate_image_colour(image, passes=1)
    assert tuple(_read(image)[4, 7, :3]) == pytest.approx((0.0, 0.0, 0.0))


