def test_bake_path_is_made_in_the_destination(tmp_path):
    destination = os.path.join(str(tmp_path), "deep", "folder")
    path = bake.resolve_bake_path("bob", destination, suffix="_ao")
    assert path == os.path.join(destination, "bob_texture_ao.png")
