def test_bake_path_without_a_destination_uses_the_default(tmp_path, monkeypatch):
    monkeypatch.setattr(bake, "get_default_bake_directory", lambda: str(tmp_path))
    assert bake.resolve_bake_path("bob", "") == os.path.join(str(tmp_path), "bob_texture.png")
    assert bake.resolve_bake_path("bob", None) == os.path.join(str(tmp_path), "bob_texture.png")


def test_bake_path_falls_back_to_temp_when_it_cannot_be_made(tmp_path):
    blocker = tmp_path / "a_file"
    blocker.write_text("not a folder")
    path = bake.resolve_bake_path("bob", str(blocker / "sub"))
    assert os.path.dirname(path) == tempfile.gettempdir()


def test_bake_image_is_created_and_reused(scratch):
    image = bake._bake_image("bake_image_reuse", 64, alpha=True, colorspace='sRGB')
    assert tuple(image.size) == (64, 64)
    assert image.colorspace_settings.name == 'sRGB'

    again = bake._bake_image("bake_image_reuse", 128, alpha=False, colorspace='Non-Color')
    assert again == image, "a rebake reuses the datablock instead of piling up .001 copies"
    assert tuple(again.size) == (128, 128)
    assert again.colorspace_settings.name == 'Non-Color'
    assert again.alpha_mode == 'NONE'


