def test_holdout_material(scratch):
    assert surface_link_source(bake._build_holdout_material()).bl_idname == 'ShaderNodeHoldout'


@pytest.mark.parametrize("key", list(bake._EXTRA_MAP_BUILDERS.keys()) + ["coverage"])
@pytest.mark.parametrize("ray_range", [None, 0.2])
def test_extra_map_materials_emit_their_value(scratch, key, ray_range):
    builder = bake._white_color if key == "coverage" else bake._EXTRA_MAP_BUILDERS[key][1]
    material = bake._build_emit_material(f"bake_emit_{key}", builder, {"ray_range": ray_range, "depth_scale": 0.1})
    source = surface_link_source(material)
    if ray_range is None:
        assert source.bl_idname == 'ShaderNodeEmission'
    else:
        # Hair further away than the range turns transparent
        assert source.bl_idname == 'ShaderNodeMixShader'
        too_far = source.inputs['Fac'].links[0].from_node
        assert too_far.operation == 'GREATER_THAN'
        assert too_far.inputs[1].default_value == pytest.approx(ray_range)
    emission = next(node for node in material.node_tree.nodes if node.bl_idname == 'ShaderNodeEmission')
    assert emission.inputs['Color'].is_linked


def test_depth_map_never_divides_by_zero(scratch):
    material = bake._build_emit_material("bake_depth_zero", bake._depth_color, {"depth_scale": 0.0})
    divide = next(node for node in material.node_tree.nodes
                  if node.bl_idname == 'ShaderNodeMath' and node.operation == 'DIVIDE')
    assert divide.inputs[1].default_value > 0.0


def test_range_limited_copies_leave_the_asset_alone(scratch):
    hair_obj = make_grid("bake_range_hair")
    original = make_material("bake_range_original")
    unconnected = make_material("bake_range_unconnected")
    output = next(node for node in unconnected.node_tree.nodes if node.bl_idname == 'ShaderNodeOutputMaterial')
    for link_ in list(output.inputs['Surface'].links):
        unconnected.node_tree.links.remove(link_)
    for material in (original, None, unconnected):
        hair_obj.data.materials.append(material)
    materials_before = len(bpy.data.materials)

    copies = bake._range_limited_copies(hair_obj, 0.3)
    assert copies[0] is not original and copies[0].name == "bake_range_original_range_limited"
    assert surface_link_source(copies[0]).bl_idname == 'ShaderNodeMixShader'
    assert surface_link_source(original).bl_idname == 'ShaderNodeBsdfPrincipled', "the asset material is untouched"
    assert copies[1] is None
    assert copies[2] is unconnected, "a material with nothing to limit is used as it is"
    assert len(bpy.data.materials) == materials_before + 1, "the useless copy must not be left behind"


