@pytest.fixture
def world_with_background(scratch):
    scene = bpy.context.scene
    previous = scene.world
    world = bpy.data.worlds.new("bake_test_world")
    world.use_nodes = True
    world.node_tree.nodes["Background"].inputs[0].default_value = (0.2, 0.3, 0.4, 1.0)
    scene.world = world
    yield world
    scene.world = previous


def _background(world):
    return tuple(world.node_tree.nodes["Background"].inputs[0].default_value)


@pytest.mark.parametrize("keep_world", [False, True])
def test_bake_settings_are_applied_and_restored(world_with_background, keep_world):
    scene = bpy.context.scene
    operator = operator_mock(BakeOperator)
    engine, transparent = scene.render.engine, scene.render.film_transparent
    samples = scene.cycles.samples
    direct = scene.render.bake.use_pass_direct

    settings = operator._store_scene_settings(scene)
    operator._apply_bake_settings(scene, 3, keep_world=keep_world)
    assert scene.render.engine == 'CYCLES'
    assert scene.render.film_transparent
    assert scene.cycles.samples == 3
    if keep_world:
        assert _background(world_with_background) == pytest.approx((0.2, 0.3, 0.4, 1.0)), \
            "the current scene lighting needs the world as it is"
    else:
        assert _background(world_with_background) == pytest.approx((0.0, 0.0, 0.0, 0.0))

    scene.render.bake.use_pass_direct = not direct
    bake._restore_scene_settings(scene, settings)
    assert (scene.render.engine, scene.render.film_transparent) == (engine, transparent)
    assert scene.cycles.samples == samples
    assert scene.render.bake.use_pass_direct == direct
    assert _background(world_with_background) == pytest.approx((0.2, 0.3, 0.4, 1.0))


def test_bake_settings_without_a_world(scratch):
    scene = bpy.context.scene
    previous = scene.world
    scene.world = None
    try:
        operator = operator_mock(BakeOperator)
        settings = operator._store_scene_settings(scene)
        assert settings["background"] is None
        operator._apply_bake_settings(scene, 1)
        bake._restore_scene_settings(scene, settings)
    finally:
        scene.world = previous


def test_guarded_runs_at_once_and_swallows_errors():
    ran = []

    @bake._guarded("do something")
    def _works():
        ran.append("works")

    @bake._guarded("fail")
    def _fails():
        ran.append("fails")
        raise RuntimeError("one step of the cleanup failed")

    assert ran == ["works", "fails"]


