def _strands_up(name="bake_light_hair", location=(0.0, 0.0, 1.5)):
    strands = []
    for x in (-0.1, 0.0, 0.1):
        strands += bundle_of_strands((x, 0.0, 0.0), count=3, length=0.3)
    return make_hair_curves(name, strands, location=location)


def test_strand_axes_follow_the_hair(scratch):
    operator = operator_mock(BakeOperator)
    direction, across_a, across_b = operator._strand_axes(_strands_up())
    assert abs(direction.z) == pytest.approx(1.0, abs=1e-3)
    for vector in (across_a, across_b):
        assert vector.length == pytest.approx(1.0)
        assert abs(vector.dot(direction)) < 1e-4
    assert abs(across_a.dot(across_b)) < 1e-4


def test_strand_axes_of_an_empty_groom(scratch):
    assert operator_mock(BakeOperator)._strand_axes(make_hair_curves("bake_light_empty", [])) is None


def test_hair_bounds(scratch):
    hair_obj = _strands_up()
    centre, radius = operator_mock(BakeOperator)._hair_bounds(hair_obj)
    assert centre.z == pytest.approx(1.5 + 0.15, abs=0.01)
    assert radius == pytest.approx(Vector((0.11, 0.01, 0.15)).length, abs=0.02)


