# Putting the scene back
# ---------------------------------------------------------------------------

def test_restore_environment_undoes_the_preparation(world_with_background):
    """Everything _prepare() changes is listed in the state, and all of it has to come back."""
    scene = bpy.context.scene
    basemesh = make_grid("bake_restore_body")
    hair_obj = make_grid("bake_restore_hair")
    bystander = make_grid("bake_restore_bystander")
    target = make_grid("bake_restore_target")
    rig = make_rig("bake_restore_rig")
    rig.data.pose_position = 'POSE'
    skin = make_material("bake_restore_skin")
    basemesh.data.materials.append(skin)
    hair_material = make_material("bake_restore_hair_material")
    hair_obj.data.materials.append(hair_material)
    operator = operator_mock(BakeOperator)

    state = {"scene": scene, "basemesh": basemesh, "hair_obj": hair_obj, "bake_target": target,
             "swapped_materials": [], "lights": []}
    state["scene_settings"] = operator._store_scene_settings(scene)
    operator._apply_bake_settings(scene, 1)
    state["hidden_objects"] = [(bystander, (bystander.hide_render, bystander.hide_viewport))]
    bystander.hide_render = bystander.hide_viewport = True
    state["original_card_visibility"] = {"visible_shadow": True}
    target.visible_shadow = False
    state["shadow_casters"] = [(basemesh, True)]
    basemesh.visible_shadow = False
    state["rest_posed_rig"] = (rig, 'POSE')
    rig.data.pose_position = 'REST'
    holdout = bake._build_holdout_material()
    state["swapped_materials"].append((basemesh, [skin]))
    basemesh.data.materials.clear()
    basemesh.data.materials.append(holdout)
    state["basemesh_material"] = holdout
    state["original_hair_materials"] = [hair_material]
    state["range_limited_materials"] = bake._range_limited_copies(hair_obj, 0.1)
    hair_obj.data.materials.clear()
    for material in state["range_limited_materials"]:
        hair_obj.data.materials.append(material)
    state["card_material"] = bake._build_ray_portal_material()
    state["lights"] = operator._add_bake_lights(scene, basemesh, hair_obj, cg.LIGHT_MODE_FIXED, 1.0)
    added_materials = [holdout, state["card_material"]] + state["range_limited_materials"]
    added_material_names = [material.name for material in added_materials]
    light_names = [light.name for light in state["lights"]]

    bake._restore_environment(state, keep_card_material=False)

    assert not bystander.hide_render and not bystander.hide_viewport
    assert target.visible_shadow
    assert basemesh.visible_shadow
    assert rig.data.pose_position == 'POSE'
    assert [slot.material for slot in basemesh.material_slots] == [skin]
    assert [slot.material for slot in hair_obj.material_slots] == [hair_material]
    for name in added_material_names:
        assert name not in bpy.data.materials, f"{name} was left behind"
    for name in light_names:
        assert name not in bpy.data.objects
    assert _background(world_with_background) == pytest.approx((0.2, 0.3, 0.4, 1.0))
    assert bpy.context.view_layer.objects.active == basemesh


def test_restore_environment_keeps_the_card_material_when_asked(scratch):
    """After a failed wrap up the card material is thrown away with the working copy, not by the restore."""
    basemesh = make_grid("bake_keep_body")
