def test_finishing_a_dead_bake_only_warns(scratch):
    """An undo during a background bake frees what the bake was working on. Touching it would crash blender."""
    body = make_grid("bake_dead_body")
    hair_obj = make_grid("bake_dead_hair")
    reports = []
    state = {"basemesh": body, "hair_obj": hair_obj, "report": lambda level, message: reports.append((level, message))}
    bpy.data.objects.remove(hair_obj)
    assert not bake._finish(state, True)
    assert reports and next(iter(reports[0][0])) == 'WARNING'


